# Pull ACS 2023 1-year B25070 for selected large MSAs via Census API
$vars = "NAME,B25070_001E,B25070_007E,B25070_008E,B25070_009E,B25070_010E,B25070_011E"
$url = "https://api.census.gov/data/2023/acs/acs1?get=$vars&for=metropolitan%20statistical%20area/micropolitan%20statistical%20area:*"
try {
  $r = Invoke-RestMethod -Uri $url -TimeoutSec 60
  $rows = @()
  for ($i=1; $i -lt $r.Count; $i++) {
    $name = $r[$i][0]
    $tot = [double]$r[$i][1]
    if ($tot -le 0) { continue }
    $b30 = [double]$r[$i][2] + [double]$r[$i][3] + [double]$r[$i][4] + [double]$r[$i][5]
    $b50 = [double]$r[$i][5]
    $pct30 = [math]::Round(100*$b30/$tot,1)
    $pct50 = [math]::Round(100*$b50/$tot,1)
    $rows += [pscustomobject]@{name=$name; tot=[int]$tot; pct30=$pct30; pct50=$pct50}
  }
  $top = $rows | Sort-Object pct30 -Descending | Select-Object -First 25
  $top | Format-Table -AutoSize
  "`n--- lowest among large (tot>150000) ---"
  $rows | Where-Object { $_.tot -gt 150000 } | Sort-Object pct30 | Select-Object -First 12 | Format-Table -AutoSize
  "`n--- US-ish check Miami ---"
  $rows | Where-Object { $_.name -match 'Miami|Cape Coral|Orlando|Tampa|Riverside|San Diego|Las Vegas|Honolulu|Fayetteville|Wichita|Pittsburgh|Des Moines|New York|Los Angeles|Boston|Seattle|Dallas|Houston|Chicago|Atlanta|Phoenix|Denver|Austin|San Jose|San Francisco' } | Sort-Object pct30 -Descending | Format-Table -AutoSize
} catch { $_.Exception.Message }

