/**
 * Rent burden: share of income renters hand to landlords (2026).
 *
 * Core question: Which US metros push the largest share of renter households
 * past 30% and past 50% of income spent on gross rent?
 *
 * Primary anchors: Census ACS table B25070 (gross rent as % of household
 * income); Harvard JCHS America's Rental Housing 2024 and the 2024
 * affordability update (ACS 2019???2023 metro panels). Severe-burden metro
 * shares draw on ACS-derived desk synthesis consistent with published
 * large-metro rankings. Not a tenant-screening product or investment advice.
 */

export type Confidence = "disclosed" | "estimated" | "carried";

export type Region =
  | "South"
  | "West"
  | "Northeast"
  | "Midwest";

export const SOURCE_NOTE =
  "Desk synthesis of Census ACS B25070 (gross rent as a percentage of household income; burden = 30%+, severe = 50%+, computed over units with a calculable ratio), Harvard Joint Center for Housing Studies America's Rental Housing 2024 and the companion Deteriorating Rental Affordability update (ACS 2019???2023 for the 100 largest metros), plus published ACS-derived metro severe-burden rankings. JCHS large-metro rates and ACS 1-year / 5-year vintages are not interchangeable ??? figures carry vintage labels. National income-band and residual-income context from JCHS. Not a credit score, rent-roll forecast, or investment recommendation.";

export const SOURCES = [
  {
    label: "Harvard JCHS ??? America's Rental Housing 2024",
    url: "https://www.jchs.harvard.edu/americas-rental-housing-2024",
  },
