  },
] as const;

/** Headline punchline ??? Florida Sun Belt metros lead the large-market panel */
export const HEADLINE = {
  topMetro: "Cape Coral???Fort Myers, FL",
  topMetroBurden30Pct: 65,
  topMetroVintage: "ACS 2023 ?? JCHS 100-largest panel",
  miamiBurden30Pct: 63,
  miamiSevere50Pct: 38,
  nationalBurden30Pct: 50,
