  largeMetrosOver50PctShare: 50,
  metrosWorsened2019to2023: 89,
  floridaTop5Count: 5,
  lowestLargeMetroBurden30Pct: 42,
  lowestLargeMetroLabel: "Des Moines / Pittsburgh / Wichita",
  under30kBurdenPct: 83,
  under30kSeverePct: 67,
  over75kBurdenPct: 13,
  westRegionBurdenPct: 52,
  southRegionBurdenPct: 50,
  northeastRegionBurdenPct: 49,
  midwestRegionBurdenPct: 45,
  tampaDelta2019to2023Ppt: 8.4,
} as const;

/** National ACS-style rent-to-income bucket shares (ACS 2024 1-yr synthesis) */
export const NATIONAL_BUCKETS: {
  id: string;
  label: string;
  sharePct: number;
  band: "unburdened" | "moderate" | "severe";
}[] = [
  { id: "lt15", label: "Under 15%", sharePct: 12.1, band: "unburdened" },
  { id: "15_25", label: "15???24.9%", sharePct: 24.6, band: "unburdened" },
  { id: "25_30", label: "25???29.9%", sharePct: 11.6, band: "unburdened" },
