"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  HEADLINE,
  INCOME_BANDS,
  METRO_BURDENS,
  NATIONAL_BUCKETS,
  NATIONAL_PATH,
  REGION_ROLLUP,
  SOURCE_NOTE,
  fmtPct,
  fmtRent,
  type Region,
} from "@/data/rent-burden-share-of-income-acs-2026-data";

// viz-types: dual-threshold metro bars, national path area+line, rent-vs-burden scatter, income-band grouped bars, ACS bucket histogram, region deltas | layout: default

type ViewId = "metros" | "path" | "scatter" | "income" | "buckets" | "regions";
type ThresholdMode = "both" | "burden30" | "severe50";
type RegionFilter = "all" | Region;
type SortMode = "burden30" | "severe50" | "delta";

const NAVY = "#1e3a5f";
const TEAL = "#0f766e";
const AMBER = "#b45309";
const ROSE = "#be123c";
const SLATE = "#64748b";
const SKY = "#0369a1";

const REGION_COLORS: Record<Region, string> = {
  South: ROSE,
  West: AMBER,
  Northeast: SKY,
  Midwest: TEAL,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function RentBurdenShareOfIncomeAcs2026Dashboard() {
  const [view, setView] = useState<ViewId>("metros");
  const [threshold, setThreshold] = useState<ThresholdMode>("both");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [sort, setSort] = useState<SortMode>("burden30");

  const metros = useMemo(() => {
    let rows =
      region === "all"
        ? [...METRO_BURDENS]
        : METRO_BURDENS.filter((m) => m.region === region);
    if (sort === "burden30")
      rows.sort((a, b) => b.burden30Pct - a.burden30Pct);
    else if (sort === "severe50")
      rows.sort((a, b) => b.severe50Pct - a.severe50Pct);
    else rows.sort((a, b) => b.delta2019to2023Ppt - a.delta2019to2023Ppt);
    return rows;
  }, [region, sort]);

  const scatterData = useMemo(
    () =>
      METRO_BURDENS.filter((m) =>
        region === "all" ? true : m.region === region,
      ).map((m) => ({
        ...m,
        x: m.medianGrossRent,
        y: threshold === "severe50" ? m.severe50Pct : m.burden30Pct,
        z: Math.max(40, Math.sqrt(m.renterHhApproxK)),
      })),
    [region, threshold],
  );

  const pathData = useMemo(
    () =>
      NATIONAL_PATH.map((d) => ({
        ...d,
        severeSharePct: d.severeSharePct ?? undefined,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="rent-burden-share-of-income-acs-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-rose-950 px-5 py-6 text-white sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-widest text-rose-200/90">
          Rent-to-income ?? ACS B25070 + JCHS large-metro panel
        </p>
        <p className="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">
          {HEADLINE.topMetro.split(",")[0]} ??{" "}
          {fmtPct(HEADLINE.topMetroBurden30Pct)} at 30%+
        </p>
        <p className="mt-2 max-w-3xl text-sm text-slate-300 sm:text-base">
          Among the 100 largest U.S. metros, Cape Coral leads at{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.topMetroBurden30Pct)}
          </span>{" "}
          of renter households past the 30% gross-rent threshold. Miami sits at{" "}
          {fmtPct(HEADLINE.miamiBurden30Pct)} with a severe (50%+) share near{" "}
          {fmtPct(HEADLINE.miamiSevere50Pct)}. Nationally, half of renters are
          cost-burdened and {fmtPct(HEADLINE.nationalSevere50Pct)} are severely
          burdened ??? {HEADLINE.nationalSevereHouseholdsM} million households.
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={view}
          onChange={setView}
          options={[
            { id: "metros", label: "Metro thresholds" },
            { id: "path", label: "National path" },
            { id: "scatter", label: "Rent vs burden" },
            { id: "income", label: "Income bands" },
            { id: "buckets", label: "ACS buckets" },
            { id: "regions", label: "Regions" },
          ]}
        />
        {(view === "metros" || view === "scatter") && (
          <ToggleGroup
            label="Region"
            value={region}
            onChange={setRegion}
            options={[
              { id: "all", label: "All" },
              { id: "South", label: "South" },
              { id: "West", label: "West" },
              { id: "Northeast", label: "Northeast" },
              { id: "Midwest", label: "Midwest" },
            ]}
          />
        )}
      </div>

      {view === "metros" && (
        <ChartCard
          title="Dual thresholds: 30%+ vs 50%+ of income on gross rent"
          subtitle="JCHS ACS 2023 large-metro 30%+ rates; severe shares ACS-derived desk synthesis. Sort and region filters below."
        >
          <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
            <ToggleGroup
              label="Show"
              value={threshold}
              onChange={setThreshold}
              options={[
                { id: "both", label: "Both" },
                { id: "burden30", label: "30%+ only" },
                { id: "severe50", label: "50%+ only" },
              ]}
            />
            <ToggleGroup
              label="Sort"
              value={sort}
              onChange={setSort}
              options={[
                { id: "burden30", label: "By 30%+" },
                { id: "severe50", label: "By 50%+" },
                { id: "delta", label: "By 2019???23 ??" },
              ]}
            />
          </div>
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={metros}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 70]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={96}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  formatter={(value, name) => [
