"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  HEADLINE,
  INCOME_BANDS,
  METRO_BURDENS,
  NATIONAL_BUCKETS,
  NATIONAL_PATH,
  REGION_ROLLUP,
  SOURCE_NOTE,
  fmtPct,
  fmtRent,
  type Region,
} from "@/data/rent-burden-share-of-income-acs-2026-data";

// viz-types: dual-threshold metro bars, national path area+line, rent-vs-burden scatter, income-band grouped bars, ACS bucket histogram, region deltas | layout: default

type ViewId = "metros" | "path" | "scatter" | "income" | "buckets" | "regions";
type ThresholdMode = "both" | "burden30" | "severe50";
type RegionFilter = "all" | Region;
type SortMode = "burden30" | "severe50" | "delta";

const NAVY = "#1e3a5f";
const TEAL = "#0f766e";
const AMBER = "#b45309";
const ROSE = "#be123c";
const SLATE = "#64748b";
const SKY = "#0369a1";

const REGION_COLORS: Record<Region, string> = {
  South: ROSE,
  West: AMBER,
  Northeast: SKY,
  Midwest: TEAL,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function RentBurdenShareOfIncomeAcs2026Dashboard() {
  const [view, setView] = useState<ViewId>("metros");
  const [threshold, setThreshold] = useState<ThresholdMode>("both");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [sort, setSort] = useState<SortMode>("burden30");

  const metros = useMemo(() => {
    let rows =
      region === "all"
        ? [...METRO_BURDENS]
        : METRO_BURDENS.filter((m) => m.region === region);
    if (sort === "burden30")
      rows.sort((a, b) => b.burden30Pct - a.burden30Pct);
    else if (sort === "severe50")
      rows.sort((a, b) => b.severe50Pct - a.severe50Pct);
    else rows.sort((a, b) => b.delta2019to2023Ppt - a.delta2019to2023Ppt);
    return rows;
  }, [region, sort]);

  const scatterData = useMemo(
    () =>
      METRO_BURDENS.filter((m) =>
        region === "all" ? true : m.region === region,
      ).map((m) => ({
        ...m,
        x: m.medianGrossRent,
        y: threshold === "severe50" ? m.severe50Pct : m.burden30Pct,
        z: Math.max(40, Math.sqrt(m.renterHhApproxK)),
      })),
    [region, threshold],
  );

  const pathData = useMemo(
    () =>
      NATIONAL_PATH.map((d) => ({
        ...d,
        severeSharePct: d.severeSharePct ?? undefined,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="rent-burden-share-of-income-acs-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-rose-950 px-5 py-6 text-white sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-widest text-rose-200/90">
          Rent-to-income ?? ACS B25070 + JCHS large-metro panel
        </p>
        <p className="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">
          {HEADLINE.topMetro.split(",")[0]} ??{" "}
          {fmtPct(HEADLINE.topMetroBurden30Pct)} at 30%+
        </p>
        <p className="mt-2 max-w-3xl text-sm text-slate-300 sm:text-base">
          Among the 100 largest U.S. metros, Cape Coral leads at{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.topMetroBurden30Pct)}
          </span>{" "}
          of renter households past the 30% gross-rent threshold. Miami sits at{" "}
          {fmtPct(HEADLINE.miamiBurden30Pct)} with a severe (50%+) share near{" "}
          {fmtPct(HEADLINE.miamiSevere50Pct)}. Nationally, half of renters are
          cost-burdened and {fmtPct(HEADLINE.nationalSevere50Pct)} are severely
          burdened ??? {HEADLINE.nationalSevereHouseholdsM} million households.
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={view}
          onChange={setView}
          options={[
            { id: "metros", label: "Metro thresholds" },
            { id: "path", label: "National path" },
            { id: "scatter", label: "Rent vs burden" },
            { id: "income", label: "Income bands" },
            { id: "buckets", label: "ACS buckets" },
            { id: "regions", label: "Regions" },
          ]}
        />
        {(view === "metros" || view === "scatter") && (
          <ToggleGroup
            label="Region"
            value={region}
            onChange={setRegion}
            options={[
              { id: "all", label: "All" },
              { id: "South", label: "South" },
              { id: "West", label: "West" },
              { id: "Northeast", label: "Northeast" },
              { id: "Midwest", label: "Midwest" },
            ]}
          />
        )}
      </div>

      {view === "metros" && (
        <ChartCard
          title="Dual thresholds: 30%+ vs 50%+ of income on gross rent"
          subtitle="JCHS ACS 2023 large-metro 30%+ rates; severe shares ACS-derived desk synthesis. Sort and region filters below."
        >
          <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
            <ToggleGroup
              label="Show"
              value={threshold}
              onChange={setThreshold}
              options={[
                { id: "both", label: "Both" },
                { id: "burden30", label: "30%+ only" },
                { id: "severe50", label: "50%+ only" },
              ]}
            />
            <ToggleGroup
              label="Sort"
              value={sort}
              onChange={setSort}
              options={[
                { id: "burden30", label: "By 30%+" },
                { id: "severe50", label: "By 50%+" },
                { id: "delta", label: "By 2019???23 ??" },
              ]}
            />
          </div>
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={metros}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 70]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={96}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  formatter={(value, name) => [
                    fmtPct(Number(value)),
                    String(name),
                  ]}
                />
                <Legend />
                {(threshold === "both" || threshold === "burden30") && (
                  <Bar
                    dataKey="burden30Pct"
                    name="???30% of income"
                    fill={NAVY}
                    radius={[0, 4, 4, 0]}
                  />
                )}
                {(threshold === "both" || threshold === "severe50") && (
                  <Bar
                    dataKey="severe50Pct"
                    name="???50% of income"
                    fill={ROSE}
                    radius={[0, 4, 4, 0]}
                  />
                )}
                <ReferenceLine
                  x={HEADLINE.nationalBurden30Pct}
                  stroke={AMBER}
                  strokeDasharray="4 4"
                  label={{
                    value: "US 30%+",
                    position: "insideTopRight",
                    fill: AMBER,
                    fontSize: 11,
                  }}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "path" && (
        <ChartCard
          title="National cost-burdened renter households"
          subtitle="JCHS America's Rental Housing path ??? household counts (area) and burden / severe shares (lines)."
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={pathData}
                margin={{ top: 12, right: 16, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 12, fill: SLATE }} />
                <YAxis
                  yAxisId="hh"
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{
                    value: "Households (M)",
                    angle: -90,
                    position: "insideLeft",
                    fill: SLATE,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  yAxisId="pct"
                  orientation="right"
                  domain={[20, 55]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="hh"
                  type="monotone"
                  dataKey="burdenedHouseholdsM"
                  name="Burdened HHs (M)"
                  fill={SKY}
                  fillOpacity={0.25}
                  stroke={SKY}
                />
                <Line
                  yAxisId="pct"
                  type="monotone"
                  dataKey="burdenSharePct"
                  name="Burden share %"
                  stroke={NAVY}
                  strokeWidth={2.5}
                  dot={{ r: 4 }}
                />
                <Line
                  yAxisId="pct"
                  type="monotone"
                  dataKey="severeSharePct"
                  name="Severe share %"
                  stroke={ROSE}
                  strokeWidth={2}
                  strokeDasharray="5 4"
                  dot={{ r: 3 }}
                  connectNulls={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Median gross rent vs burden share"
          subtitle="Bubble size ??? renter household count. High-rent / high-income metros (e.g. San Jose) can sit below Sun Belt peers on burden share."
        >
          <div className="mb-4">
            <ToggleGroup
              label="Y-axis"
              value={threshold === "severe50" ? "severe50" : "burden30"}
              onChange={(v) =>
                setThreshold(v === "severe50" ? "severe50" : "burden30")
              }
              options={[
                { id: "burden30", label: "30%+ share" },
                { id: "severe50", label: "50%+ share" },
              ]}
            />
          </div>
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Median rent"
                  tickFormatter={(v) => `$${Math.round(v / 100) / 10}k`}
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{
                    value: "Median gross rent",
                    position: "insideBottom",
                    offset: -2,
                    fill: SLATE,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Burden"
                  domain={[15, 70]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <ZAxis type="number" dataKey="z" range={[60, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value, name) => {
                    if (name === "x" || name === "Median rent")
                      return [fmtRent(Number(value)), "Median rent"];
                    if (name === "y" || name === "Burden")
                      return [fmtPct(Number(value)), "Burden share"];
                    return [String(value), String(name)];
                  }}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.short ?? ""
                  }
                />
                <Scatter data={scatterData} name="Metros">
                  {scatterData.map((d) => (
                    <Cell
                      key={d.id}
                      fill={REGION_COLORS[d.region]}
                      fillOpacity={0.85}
                    />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-2 flex flex-wrap gap-3 text-xs text-slate-500">
            {(Object.keys(REGION_COLORS) as Region[]).map((r) => (
              <span key={r} className="inline-flex items-center gap-1.5">
                <span
                  className="inline-block h-2.5 w-2.5 rounded-full"
                  style={{ background: REGION_COLORS[r] }}
                />
                {r}
              </span>
            ))}
          </div>
        </ChartCard>
      )}

      {view === "income" && (
        <ChartCard
          title="Burden climbs down the income ladder"
          subtitle="JCHS 2023 ??? share of renter households cost-burdened and severely burdened by income band."
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={INCOME_BANDS}
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 12, fill: NAVY }} />
                <YAxis
                  domain={[0, 100]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <Tooltip
                  formatter={(value) => fmtPct(Number(value))}
                />
                <Legend />
                <Bar
                  dataKey="burden30Pct"
                  name="???30%"
                  fill={NAVY}
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey="severe50Pct"
                  name="???50%"
                  fill={ROSE}
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "buckets" && (
        <ChartCard
          title="National ACS rent-to-income distribution"
          subtitle="Share of renter households in each gross-rent-to-income bucket (ACS 2024 1-year synthesis of B25070)."
        >
          <div className="h-[340px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart
                data={NATIONAL_BUCKETS}
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11, fill: SLATE }} />
                <YAxis
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <Tooltip formatter={(value) => fmtPct(Number(value), 1)} />
                <Area
                  type="monotone"
                  dataKey="sharePct"
                  name="Share of renters"
                  stroke={NAVY}
                  fill={TEAL}
                  fillOpacity={0.35}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-3">
            {(["unburdened", "moderate", "severe"] as const).map((band) => {
              const sum = NATIONAL_BUCKETS.filter((b) => b.band === band).reduce(
                (s, b) => s + b.sharePct,
                0,
              );
              const label =
                band === "unburdened"
                  ? "Under 30%"
                  : band === "moderate"
                    ? "30???49.9%"
                    : "50%+";
              return (
                <div
                  key={band}
                  className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-sm"
                >
                  <div className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                    {label}
                  </div>
                  <div className="text-lg font-bold text-slate-900">
                    {fmtPct(sum, 1)}
                  </div>
                </div>
              );
            })}
          </div>
        </ChartCard>
      )}

      {view === "regions" && (
        <ChartCard
          title="Census region burden shares and 2019???2023 climb"
          subtitle="JCHS regional rollup ??? South and West lead both level and post-2019 deterioration."
        >
          <div className="h-[340px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={REGION_ROLLUP}
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="region" tick={{ fontSize: 12, fill: NAVY }} />
                <YAxis
                  yAxisId="lvl"
                  domain={[40, 55]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  yAxisId="dlt"
                  orientation="right"
                  domain={[0, 5]}
                  tickFormatter={(v) => `+${v}`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="lvl"
                  dataKey="burden30Pct"
                  name="2023 burden share"
                  radius={[4, 4, 0, 0]}
                >
                  {REGION_ROLLUP.map((r) => (
                    <Cell key={r.region} fill={REGION_COLORS[r.region]} />
                  ))}
                </Bar>
                <Line
                  yAxisId="dlt"
                  type="monotone"
                  dataKey="delta2019to2023Ppt"
                  name="2019???23 ?? (ppt)"
                  stroke={NAVY}
                  strokeWidth={2.5}
                  dot={{ r: 5 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

